const contactData = $input.item.json.contactData;

// Parse if string, otherwise use as-is
const data = typeof contactData === 'string' ? JSON.parse(contactData) : contactData;

// Validate required fields
if (!data['Full Name'] || !data['Email Address']) {
  throw new Error('Full Name and Email Address are required');
}

// Validate email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(data['Email Address'])) {
  throw new Error('Invalid email format');
}

return { json: data };
